theme.css:
#wemd{color:#374151;background-color:#ffffff;font-family:'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Noto Sans SC', 'Microsoft YaHei', sans-serif;font-size:15px;line-height:1.8;letter-spacing:0.02em;text-align:justify;padding:32px 16px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.2em;text-indent:0}
#wemd h1{font-size:26px;font-weight:800;color:#1C1917;margin-top:2em;margin-bottom:1em;text-align:left}
#wemd h2{font-size:20px;font-weight:800;color:#1C1917;margin-top:2.2em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid #DC2626;padding-bottom:.4em}
#wemd h3{font-size:17px;font-weight:700;color:#1C1917;margin-top:1.6em;margin-bottom:0.6em}
#wemd h3::before{content:"· ";color:#DC2626}
#wemd h4{font-size:15px;font-weight:600;color:#9CA3AF;margin-top:1.3em;margin-bottom:0.5em}
#wemd blockquote{border-left:4px solid #FECACA;background:#FEF2F2;padding:14px 20px;color:#374151;font-style:normal;margin:1.2em 0}
#wemd code{background-color:#F3F4F6;color:#1F2937;padding:2px 6px;border-radius:4px;font-size:0.9em;font-family:ui-monospace, 'Cascadia Code', 'Fira Code', Menlo, Monaco, Consolas, monospace}
#wemd pre{background:#F3F4F6;border-radius:8px;padding:16px 20px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid #FEE2E2;padding:10px 14px}
#wemd th{background:#FEF2F2}
#wemd tr:nth-child(even){background:#FEF2F2}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:disc}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:6px}
#wemd li::marker{color:#DC2626}
#wemd hr{border:0;border-top:1px solid #FCA5A5;margin:2em 0;width:100%}
#wemd img{max-width:100%;height:auto;border-radius:8px}
#wemd figcaption{font-size:12px;color:#9CA3AF;text-align:center}
#wemd a{color:#DC2626;text-decoration:none}
#wemd strong{color:#DC2626;font-weight:700}
#wemd mark{background:#FEE2E2;padding:2px 4px;border-radius:3px}
